const { transcript, matrix } = items[0].json;
const normalize = t => t.toLowerCase().replace(/[^\w\s]/g,' ').trim();
const tokens = normalize(transcript).split(' ');
const totalTokens = tokens.length || 1;
const breakdown = matrix.map(r=>{
  let cumplimiento=0;
  if(r.tipo==='always'){ cumplimiento=1; }
  else if(r.tipo==='keyword'){
    const alts=r.patron.split('|').map(a=>normalize(a));
    const found=alts.filter(a=>transcript.includes(a));
    cumplimiento=found.length/alts.length;
    if(cumplimiento>r.umbral) cumplimiento=1;
  } else if(r.tipo==='regex'){
    const regex=new RegExp(r.patron,'g');
    const matches=transcript.match(regex);
    cumplimiento=Math.min((matches?matches.length:0)/totalTokens,1);
    if(cumplimiento>r.umbral) cumplimiento=1;
  }
  const puntaje_parcial=cumplimiento*r.peso;
  return {...r,cumplimiento,puntaje_parcial};
});
const total=breakdown.reduce((s,r)=>s+r.puntaje_parcial,0);
return [{ json: { total, breakdown } }];
